        ["Hooray! I actually did it! Hogera is safe!"] = "Ура! Я впорався! Їжакія в безпеці!", -- A_Space_Adventure:final
        ["Hooray! I've found it, now I have to get back to Captain Lime!"] = "Ура, дістав! Слід повернутись до капітана Лайма!", -- A_Space_Adventure:fruit02
        ["Hooray! You are a champion!"] = "Ура! Ви чемпіон!", -- A_Space_Adventure:ice02
        ["Hopeless case"] = "Безнадійний випадок", -- User_Mission_-_RCPlane_Challenge
        ["Hop on top of the next flower and advance to the left coast."] = "Застрибніть на наступну квітку й прямуйте на лівий берег.", -- A_Classic_Fairytale:journey
        ["Horns"] = "Рогата", -- HedgeEditor
        ["Hostage Situation"] = "Їжаки в заручниках", -- A_Classic_Fairytale:family
        ["How can I ever repay you for saving my life?"] = "Чим я можу віддячити вам за порятунок?", -- A_Classic_Fairytale:journey
        ["How come in a village full of warriors, it's up to me to save it?"] = "Повне село воїнів, а рятувати його мушу я?", -- A_Classic_Fairytale:dragon
        ["How could you betray us?"] = "Як ви могли нас зрадити?", -- A_Classic_Fairytale:queen
        ["How difficult would you like it to be?"] = "Наскільки складне випробування вас цікавить?", -- A_Classic_Fairytale:first_blood
        ["HOW DO THEY KNOW WHERE WE ARE?"] = "ЗВІДКИ ВОНИ ЗНАЮТЬ, ДЕ МИ?", -- A_Classic_Fairytale:united
        ["However, if you fail to do so, she dies a most violent death, just like your friend! Muahahaha!"] = "Проте якщо вам не вдасться, вона загине жорстокою смертю, як і ваш друг! Муахахаха!", -- A_Classic_Fairytale:journey
        ["However, if you fail to do so, she dies a most violent death! Muahahaha!"] = "Проте якщо вам не вдасться, вона загине жорстокою смертю! Муахахаха!", -- A_Classic_Fairytale:journey
        ["However, my mates don't agree with me on letting you go..."] = "Проте інші не згодні з моїм рішенням вас відпустити…", -- A_Classic_Fairytale:dragon
        ["However, the army of %s is about to attack any moment now."] = "Проте %s можуть напасти будь-якої миті.", -- A_Space_Adventure:fruit01
        ["How to Rope"] = "Як користуватись мотузкою", -- Basic_Training_-_Rope
        ["How would you like being discriminated against?"] = "Вам би сподобалось, якби вас дискримінували?", -- A_Classic_Fairytale:queen
        ["Huh?"] = "Га?", -- A_Classic_Fairytale:backstab, A_Classic_Fairytale:queen
        ["Hunter"] = "Мисливець", --Bazooka, Shotgun, SniperRifle
        ["I ain't gonna sit around no more!"] = "Я б іще з вами посидів, але вже час!", -- A_Classic_Fairytale:queen
        ["I already said I'm sorry!"] = "Я вже казав, що перепрошую!", -- A_Classic_Fairytale:epil
        ["I always suspected him!"] = "Я завжди його підозрював!", -- A_Classic_Fairytale:epil
        ["I am going to leave the kids play by themselves."] = "Час лишити дітей гратися на самоті.", -- A_Classic_Fairytale:queen
        ["I am not ready for this planet yet. I should visit it when I have found all the other device parts."] = "Ще не час для цієї планети. Відвідаю, коли знайду решту запчастин пристрою.", -- A_Space_Adventure:cosmos
        ["I am sorry but I was looking for a device that may be hidden somewhere around here."] = "Перепрошую, я шукаю пристрій, який сховано десь тут.", -- A_Space_Adventure:fruit02
        ["I believe there's more of them."] = "Думаю, це ще були не всі.", -- A_Classic_Fairytale:backstab
        ["I cannot let you go any further! … burp …"] = "Далі я вас… гик… не пущу!", -- A_Classic_Fairytale:queen
        ["I can see you have been training diligently."] = "Бачу, що ви старанно готувались.", -- A_Classic_Fairytale:first_blood
        ["I can't believe how blind we were."] = "Не можу повірити, наскільки сліпі ми були.", -- A_Classic_Fairytale:epil
        ["I can't believe it worked!"] = "Не віриться, що це спрацювало!", -- A_Classic_Fairytale:shadow
        ["I can't believe this!"] = "Не вірю власним вухам!", -- A_Classic_Fairytale:enemy
        ["I can't believe what I'm hearing!"] = "Не вірю власним вухам!", -- A_Classic_Fairytale:backstab
        ["I can't let you go further because …"] = "Далі я вас не пущу, тому що…", -- A_Classic_Fairytale:queen
        ["I can't wait any more, I have to save myself!"] = "Не можу більше чекати, треба рятуватись!", -- A_Classic_Fairytale:shadow
        ["Ice Jake"] = "Морозенко", -- A_Space_Adventure:ice01
        ["I could just teleport myself there..."] = "Я міг би просто туди телепортуватись…", -- A_Classic_Fairytale:family
        ["Icy Girder: [3]"] = "Слизька балка: [3]", -- HedgeEditor
        ["Icy Land: [3]"] = "Крига: [3]", -- HedgeEditor
        ["Icy Land"] = "Крига", -- HedgeEditor
        ["I'd better get going myself."] = "Піду-но туди і я.", -- A_Classic_Fairytale:journey
        ["Identity Thief"] = "Самозванець", -- Mutant
        ["I didn't until about a month ago."] = "Уже місяць — тільки й розмов про це.", -- A_Classic_Fairytale:enemy
        ["I don't care. It's worth a fortune! Good bye, you idiot!"] = "Байдуже. Він коштує цілий статок! Бувай, дурнику!", -- A_Space_Adventure:fruit02
        ["I don't know if I can forget what you've done!"] = "Не знаю, чи зможу коли-небудь забути, як ви мені нашкодили!", -- A_Classic_Fairytale:epil
        ["I don't know who I can trust anymore."] = "Навіть не знаю, кому тепер можна довіряти.", -- A_Classic_Fairytale:epil
        ["I don't like your tone! You're hurting me!"] = "Мені не до вподоби ваш тон! Ви робите мені боляче!", -- A_Classic_Fairytale:queen
        ["I feel something...a place! They will arrive near the circles!"] = "Я щось відчуваю… місце! Вони з'являться поблизу кілець!", -- A_Classic_Fairytale:backstab
        ["If only I had a way..."] = "Знати б тільки, як…", -- A_Classic_Fairytale:backstab
        ["If only I were given a chance to explain my being here..."] = "Якби лише мені дозволили пояснити, що я тут роблю…", -- A_Classic_Fairytale:first_blood
        ["If only one enemy is left, you'll get bonus ammo."] = "Якщо залишиться лише один ворог, ви здобудете додаткову зброю.", -- A_Space_Adventure:death02
        ["I forgot that she's the daughter of the chief, too..."] = "А ось і донька вождя…", -- A_Classic_Fairytale:backstab
        ["I found it! Hooray!"] = "Знайшов! Ура!", -- A_Space_Adventure:desert01
        ["If some good old explosives were enough to save Hogera …"] = "Якщо трохи старої доброї вибухівки було достатньо, щоб врятувати Їжакію…", -- A_Space_Adventure:final
        ["If they try coming here, they can have a taste of my delicious knuckles!"] = "Якщо вони сюди сунуться, то відвідають моєї березової каші!", -- A_Classic_Fairytale:united
        ["If you agree to provide the information we need, you will be spared!"] = "Якщо надасте потрібні нам дані, вас не чіпатимуть!", -- A_Classic_Fairytale:shadow
        ["If you can get that crate fast enough, your beloved \"princess\" may go free."] = "Якщо дістанете ящик достатньо швидко, я відпущу вашу кохану «принцесу».", -- A_Classic_Fairytale:journey
        ["If you decide to help us, though, we will no longer need to find a new governor for the island."] = "Якщо вирішите нам допомагати, то нам більше не доведеться шукати нового голову острова.", -- A_Classic_Fairytale:shadow
        ["If you don't want to slip away, you have to keep moving!"] = "Щоб не скочуватись, продовжуйте рух!", -- Basic_Training_-_Movement
        ["If you get stuck, use your Desert Eagle or restart the mission!"] = "Якщо застрягнете, скористайтесь Пустельним орлом чи перезапустіть місію!", -- A_Classic_Fairytale:journey
        ["If you help us you can keep the device if you find it but we'll keep everything else."] = "Якщо допоможете нам, лишайте пристрій собі, а ми візьмемо решту.", -- A_Space_Adventure:fruit02
        ["If you hurt an enemy, you'll get one third of the damage dealt."] = "При пораненні ворога ви отримуватимете третину ушкодження.", -- A_Space_Adventure:death02
        ["If you injure a hedgehog you'll get 35% of the damage dealt."] = "При пораненні їжака ви отримуватимете 35% ушкодження.", -- A_Space_Adventure:death02
        ["If you just don’t care …"] = "Якщо вам справді байдуже…", -- Continental_supplies
        ["If you kill a hedgehog with the respective weapon your health points will be set to 100."] = "При вбивстві їжака відповідною зброєю вам буде відновлено 100 очок здоров'я.", -- A_Space_Adventure:death02
        ["If you kill an enemy, your health will be set to 100."] = "При вбивстві ворога вам буде відновлено 100 очок здоров'я.", -- A_Space_Adventure:death02
        ["If you know what I mean..."] = "Якщо ви розумієте, про що я…", -- A_Classic_Fairytale:shadow
        ["If you miss a shot while trying to|re-attach, your rope is gone, too!"] = "Якщо не влучити під час повторного кидка,|мотузку буде втрачено!", -- Basic_Training_-_Rope
        ["If you say so..."] = "Як скажете…", -- A_Classic_Fairytale:shadow
        ["If you skip a turn then the turn time left will be added to your next turn."] = "Пропуск ходу додає залишок часу на наступний хід.", -- A_Space_Adventure:fruit03
        ["If you wish to replay, there are other possible endings, too!"] = "Можете пройти її ще раз, відкриваючи інші кінцівки!", -- A_Classic_Fairytale:epil
        ["Igmund"] = "Зигмунд", -- User_Mission_-_Nobody_Laugh
        ["I grew sick of the oppression! I broke free!"] = "Я втомився від пригноблення! Тепер я вільний!", -- A_Classic_Fairytale:queen
        ["I guess I can't go far without fuel!"] = "Без палива я далеко не полечу!", -- A_Space_Adventure:cosmos
        ["I guess we lost him!"] = "Йой, він утік!", -- A_Space_Adventure:cosmos
        ["I guess you'll have to kill them."] = "Гадаю, вам доведеться їх вбити.", -- A_Classic_Fairytale:dragon
        ["I have come to make you an offering..."] = "Я прийшов із пропозицією…", -- A_Classic_Fairytale:shadow
        ["I have heard that the local tribes say that many years ago some PAotH scientists were dumping their waste here."] = "Місцеві племена кажуть, що багато років тому група вчених ПАЇ скидала сюди відходи.", -- A_Space_Adventure:desert01
        ["I have more important things to do!"] = "У мене ще чимало справ!", -- A_Classic_Fairytale:queen
        ["I have no idea where that mole disappeared...Can you see it?"] = "Гадки не маю, куди подівся той кріт… Ви його бачите?", -- A_Classic_Fairytale:shadow
        ["I have only 3 hogs available and they are all cadets."] = "У мене лише троє їжаків і всі вони новобранці.", -- A_Space_Adventure:fruit01
        ["I have to follow that alien."] = "Цікаво, куди приведе мене цей прибулець.", -- A_Classic_Fairytale:backstab
        ["I have to get back to the village!"] = "Треба повернутись до села!", -- A_Classic_Fairytale:shadow
        ["I have to reach the surface as quickly as I can."] = "Треба якнайшвидше дістатись поверхні.", -- A_Space_Adventure:desert02
        ["I hope you are prepared for a small challenge, young one."] = "Сподіваюся, ви готові до маленького випробування, юначе.", -- A_Classic_Fairytale:first_blood
        ["I just don't want to sink to your level."] = "Просто не хочу опускатись до вашого рівня.", -- A_Classic_Fairytale:backstab
        ["I just forgot all checkpoints of incomplete missions."] = "Я забув усі контрольні точки незавершених місій.", -- A_Space_Adventure:cosmos
        ["I just found out that they have captured your princess!"] = "Щойно дізнався, що вони захопили вашу принцесу!", -- A_Classic_Fairytale:family
        ["I just want the strange device you found!"] = "Мені треба лише дивний пристрій, який ви знайшли!", -- A_Space_Adventure:ice01
        ["I just wonder where Ramon and Spiky disappeared..."] = "Куди ж це поділись Ромко й Сироїжка?", -- A_Classic_Fairytale:journey
        ["I know and I'm terribly sorry!"] = "Я знаю, але мені дуже шкода!", -- A_Classic_Fairytale:epil
        ["I know, my hero!"] = "Я знаю, мій герою!", -- A_Classic_Fairytale:epil
        ["I know that your resources are low due to the battle but I'll send two of my best hogs to assist you."] = "Через битву вам бракує ресурсів, але я надішлю двох моїх найкращих їжаків вам на поміч.", -- A_Space_Adventure:fruit02
        ["I … like being with you, too."] = "Мені… також добре з вами.", -- A_Classic_Fairytale:epil
        ["I'll get him!"] = "Я його спиню!", -- A_Space_Adventure:cosmos
        ["I'll hold them off while you return to the village!"] = "Я їх затримаю, а ви поверніться до села!", -- A_Classic_Fairytale:shadow
        ["I'll let you know whatever I know about him if you manage to catch me 3 times."] = "Розповім усе, що про нього знаю, якщо тричі мене впіймаєте.", -- A_Space_Adventure:moon02
        ["I'll make good use of it."] = "Постараюсь її не змарнувати.", -- A_Space_Adventure:cosmos
        ["I'll protect you!"] = "Я вас захищатиму!", -- A_Classic_Fairytale:epil
        ["I love Dense Cloud now!"] = "Я закохана в Шептуна!", -- A_Classic_Fairytale:epil
        ["I love you."] = "Я кохаю вас.", -- A_Classic_Fairytale:epil
        ["I'm afraid I can't let you proceed!"] = "Боюся, далі я вас пустити не можу!", -- A_Classic_Fairytale:queen
        ["I'm afraid we cannot afford that."] = "Боюся, це надто цінна втрата для нас.", -- A_Classic_Fairytale:queen
        ["Imagine those targets are the wolves that killed your parents! Take your anger out on them!"] = "Уявіть, що мішені — це вовки, які вбили ваших батьків! Розізліться на них!", -- A_Classic_Fairytale:first_blood
        ["I'm...alive? How? Why?"] = "Я… живий? Як? Чому?", -- A_Classic_Fairytale:backstab
        ["I'm a ninja."] = "Я — ніндзя.", -- A_Classic_Fairytale:dragon
        ["I marked the place of their arrival. You're welcome!"] = "Я позначив, куди вони прибуватимуть. Можете не дякувати!", -- A_Classic_Fairytale:backstab
        ["I may lost this battle, but I haven't lost the war yet!"] = "Може, в цій битві я й зазнав поразки, але у війні я переможу!", -- A_Space_Adventure:moon01
        ["I'm certain that this is a misunderstanding, fellow hedgehogs!"] = "Товариші їжаки, певно, трапилося непорозуміння!", -- A_Classic_Fairytale:first_blood
        ["I mean, none of you ceased to live."] = "Маю на увазі, всі ваші родичі живі.", -- A_Classic_Fairytale:enemy
        ["I'm getting old for this!"] = "Я вже застарий для цього!", -- A_Classic_Fairytale:family
        ["I'm getting thirsty..."] = "Випити б чогось…", -- A_Classic_Fairytale:family
        ["I'm glad this is over!"] = "Радий, що це все скінчилось!", -- A_Classic_Fairytale:epil
        ["I'm here to help you rescue her."] = "Я тут, щоб допомогти вам її врятувати.", -- A_Classic_Fairytale:family
        ["I'm living a dream!"] = "Я живу, ніби в прекрасному сні!", -- A_Classic_Fairytale:queen
        ["I'm not sure about that!"] = "Щось мені це все не до вподоби!", -- A_Classic_Fairytale:united
        ["IMPORTANT: To see the mission panel again, hold the mission panel key."] = "ВАЖЛИВО: Щоб побачити панель місії знову, затисніть клавішу панелі місії.", -- Basic_Training_-_Movement
        ["IMPORTANT: To see the mission panel again, pause the game."] = "ВАЖЛИВО: Щоб побачити панель місії знову, призупиніть гру.", -- Basic_Training_-_Movement
        ["Impressive...you are still dry as the corpse of a hawk after a week in the desert..."] = "Вражає… ви досі сухі, ніби яструб після тижня в пустелі…", -- A_Classic_Fairytale:first_blood
        ["%i ms"] = "%i мс", -- Gravity
        ["I'm so glad this is finally over!"] = "Я так радий, що це все нарешті позаду!", -- A_Space_Adventure:final
        ["I'm so scared!"] = "Мені лячно!", -- A_Classic_Fairytale:united
        ["I'm still low on hogs. If you are not afraid I could use a set of extra hands."] = "Мені все ще бракує їжаків. Якщо не боїтесь, мені не завадить ваша допомога.", -- A_Space_Adventure:fruit02
        ["I'm still with the aliens."] = "Я все ще на боці прибульців.", -- A_Classic_Fairytale:queen
        ["I'm terribly sorry!"] = "Йой, перепрошую!", -- A_Classic_Fairytale:queen
        ["I'm the spy! I've been giving you out!"] = "Шпигунка — це я! Саме я вас видавала весь цей час!", -- A_Classic_Fairytale:queen
        ["In am also entrusting you with some rope."] = "Довірю вам трохи мотузки.", -- A_Space_Adventure:cosmos
        ["In case you haven't noticed, I'm a woman, too!"] = "Якщо ви не помітили, я теж дівчина!", -- A_Classic_Fairytale:queen
        ["Increase the dust storm damage by sacrificing|your invulnerable ammo."] = "Збільшує втрати від пилової бурі,|відбираючи у вас невразливість.", -- Continental_supplies
        ["Incredible..."] = "Неймовірно...", -- A_Classic_Fairytale:shadow
        ["Indestructible Girder: [2]"] = "Незнищенна балка: [2]", -- HedgeEditor
        ["Indestructible Land: [2]"] = "Незнищенна земля: [2]", -- HedgeEditor
        ["Indestructible Land"] = "Незнищенна земля", -- HedgeEditor
        ["In each round, the worst hedgehog of the round is eliminated."] = "В кожному раунді їжак з останнім результатом вибуває.", -- TrophyRace
        ["I need to find the others!"] = "Мушу знайти інших!", -- A_Classic_Fairytale:backstab
        ["I need to get to the other side of this island, fast!"] = "Треба якнайшвидше дістатись на другий бік острова!", -- A_Classic_Fairytale:journey
        ["I need to move the tribe!"] = "Треба евакуювати плем'я!", -- A_Classic_Fairytale:united
        ["I need to prevent their arrival!"] = "Треба перешкодити їхній появі!", -- A_Classic_Fairytale:backstab
        ["I need to warn the others."] = "Треба попередити інших.", -- A_Classic_Fairytale:backstab
        ["In fact, you are the only one that's been acting strangely."] = "Поки що ви єдині, хто поводиться дивно.", -- A_Classic_Fairytale:backstab
        ["Initial health: %d"] = "Початкове здоров'я: %d", -- Continental_supplies
        ["Initiate escape wish!"] = "Бажання зникнути обчислено!", -- A_Classic_Fairytale:queen
        ["In order to get to the other side, you need to get rid of the crates first."] = "Щоб дістатись на другий берег, спершу позбудьтесь ящиків.", -- A_Classic_Fairytale:dragon
        ["Insanity!"] = "Божевілля!", -- Mutant
        ["Inside %d"] = "Усередині %d", -- WxW
        ["Inside"] = "Усередині", -- WxW
        ["Instructions"] = "Вказівки", -- Basic_Training_-_Flying_Saucer
        ["Instructor"] = "Інструктор", -- 01#Boot_Camp, User_Mission_-_Dangerous_Ducklings
        ["Insufficient Power"] = "Бракує енергії", -- Construction_Mode
        ["Interesting idea, haha!"] = "Хаха, цікава ідея!", -- A_Classic_Fairytale:enemy
        ["Interesting! Last time you said you killed a cannibal!"] = "Як цікаво! Минулий раз ви казали, що вбили канібала!", -- A_Classic_Fairytale:backstab
        ["In the Ice Planet Flying Saucer Stadium ..."] = "На Стадіоні НЛО Льодової планети…", -- A_Space_Adventure:ice02
        ["In the meantime, take these and return to your \"friend\"!"] = "Тим часом візьміть ось це й поверніться до «друга»!", -- A_Classic_Fairytale:shadow
        ["In the stadium, where the best pilots compete ..."] = "На стадіоні, де змагаються найкращі пілоти…", -- A_Space_Adventure:ice02
